function canonicalValue(key,v){v=clean(v);if(!v)return '';const n=normKey(v),aliases=VALUE_ALIASES[key]||{},alias=aliases[n];if(alias)return alias;const values=key==='countries'?COUNTRY_NAMES:(LIST_FIELDS[key]?.defaults||[]);const exact=values.find(x=>normKey(x)===n);if(exact)return exact;const candidates=new Set(values.filter(x=>normKey(x).startsWith(n)));for(const [a,target] of Object.entries(aliases))if(a.startsWith(n))candidates.add(target);return candidates.size===1?[...candidates][0]:v;}
