function normalizeLegacyPersonal(raw,legacyPlaces=[]){
  const out={};
  const add=(placeId,x={})=>{if(!placeId)return;out[`local-owner:${placeId}`]={rating:+(x.rating||0),favourite:!!(x.favourite||x.saved||x.status==='favourite'),want:!!(x.want||x.wantToGo||x.want_to_visit||x.status==='want'),visited:!!(x.visited||x.status==='visited'),privateNote:clean(x.privateNote||x.private_note||x.note),lastVisited:x.lastVisited||x.last_visited||'',wouldGoAgain:clean(x.wouldGoAgain||x.would_go_again||'')};};
  if(Array.isArray(raw)){raw.forEach(x=>add(x.placeId||x.place_id,x));}
  else if(raw&&typeof raw==='object'){
    Object.entries(raw).forEach(([k,x])=>{
      if(k.includes(':')) out[k]=Object.assign({rating:0,favourite:false,want:false,visited:false,privateNote:'',lastVisited:'',wouldGoAgain:''},x||{});
      else add(k,x||{});
    });
  }
  // Older builds sometimes kept rating/status on the place itself.
  legacyPlaces.forEach(p=>{if((p.rating||p.status)&&!out[`local-owner:${p.id}`])add(p.id,p);});
  return out;
}
