  fillDatalist('placeTypeList',mergedListValues('placeTypes'));fillDatalist('cuisineList',mergedListValues('cuisines'));fillDatalist('countryList',mergedListValues('countries'));fillDatalist('regionList',mergedListValues('regions'));fillDatalist('cityList',mergedListValues('cities'));fillDatalist('suburbList',mergedListValues('suburbs'));fillDatalist('mealTypesList',mergedListValues('mealTypes'));fillDatalist('greatForList',mergedListValues('greatFor'));fillDatalist('featuresList',mergedListValues('features'));fillDatalist('dietaryList',mergedListValues('dietary'));fillDatalist('tagsList',mergedListValues('tags'));
