async function parseImportFilesLegacy(files){const out=[];for(const f of files){const text=await f.text();if(f.name.toLowerCase().endsWith('.csv')){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);if(!lines.length)continue;const headers=splitCsvLine(lines[0]);for(const line of lines.slice(1)){const vals=splitCsvLine(line);const o={};headers.forEach((h,i)=>o[h]=vals[i]||'');const p=normaliseImported(o,f.name.replace(/\.[^.]+$/,''));if(p)out.push(p);}}else{try{const j=JSON.parse(text);const rows=j.type==='FeatureCollection'?j.features:Array.isArray(j)?j:(j.locations||j.places||j.features||[j]);for(const o of rows){const p=normaliseImported(o,f.name.replace(/\.[^.]+$/,''));if(p)out.push(p);}}catch{}}}return out;}
