  return canonicalPlace({id:uid(),name,placeType:osmPlaceType(r),cuisine:rawCuisine,country:clean(a.country),stateRegion:clean(a.state||a.region||a.state_district),city:clean(a.city||a.town||a.village||a.municipality),suburb:clean(a.suburb||a.neighbourhood||a.quarter||a.city_district||a.borough),address:clean(r?.display_name),lat,lng,price:'',phone:clean(x.phone||x['contact:phone']||''),website:clean(x.website||x['contact:website']||''),googleMapsUrl:clean(r?._googleMapsUrl)||googleMapsSearchUrl(name,r?.display_name,lat,lng),bookingUrl:clean(x['contact:booking']||x.reservation||''),mealTypes:[],greatFor:[],features:[],dietary:[],tags:[],mustTry:'',notes:'',sourceName:'OpenStreetMap',sourceId:osmId?`${osmType}:${osmId}`:'',sourceUrl,sourceCheckedAt:nowISO()});
