async function runOnlinePlaceSearch(e){
  e?.preventDefault?.();if(!canEdit())return;const q=clean($('onlinePlaceQuery').value);if(q.length<3)return $('onlinePlaceStatus').textContent='Enter a place name, location, or Google Maps link.';if(!navigator.onLine)return $('onlinePlaceStatus').textContent='You appear to be offline. Use manual entry, or try again when connected.';
  try{$('onlinePlaceSearchBtn').disabled=true;$('onlinePlaceStatus').textContent='Searching…';$('onlinePlaceResults').innerHTML='';let data=[];
    if(CFG.mode!=='local'){const out=await cfFetch(`/api/public?action=place-search&q=${encodeURIComponent(q)}`);data=out.results||[];}
    else {let query=q;if(/^https?:\/\//i.test(q)){try{const u=new URL(q),m=u.href.match(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/);query=decodeURIComponent((u.pathname.match(/\/place\/([^/]+)/)||[])[1]||u.searchParams.get('q')||'').replace(/\+/g,' ');if(m&&!query)query=`${m[1]},${m[2]}`;}catch{}}const u=new URL('https://nominatim.openstreetmap.org/search');u.searchParams.set('q',query);u.searchParams.set('format','jsonv2');u.searchParams.set('addressdetails','1');u.searchParams.set('extratags','1');u.searchParams.set('namedetails','1');u.searchParams.set('limit','8');const res=await fetch(u.href,{headers:{Accept:'application/json'}});if(!res.ok)throw new Error(`Online search failed (${res.status})`);data=await res.json();if(/^https?:\/\//i.test(q))data=data.map(x=>({...x,_googleMapsUrl:q}));}
    onlineSearchResults=Array.isArray(data)?data:[];$('onlinePlaceStatus').textContent=onlineSearchResults.length?`${onlineSearchResults.length} possible match${onlineSearchResults.length===1?'':'es'} — choose the correct one.`:'No matches found.';renderOnlineResults();
  }catch(err){onlineSearchResults=[];$('onlinePlaceResults').innerHTML='';$('onlinePlaceStatus').textContent=err.message||'Online search could not be completed. You can still enter the place manually.';}finally{$('onlinePlaceSearchBtn').disabled=false;}
}

function flattenObject(obj,prefix='',out={}){if(obj==null)return out;if(Array.isArray(obj)){obj.forEach((v,i)=>flattenObject(v,`${prefix}${i}.`,out));return out;}if(typeof obj==='object'){for(const [k,v] of Object.entries(obj))flattenObject(v,`${prefix}${k}.`,out);return out;}out[prefix.replace(/\.$/,'')]=obj;return out;}
function pickFlat(flat,names){const entries=Object.entries(flat);for(const n of names){const nk=normKey(n);const hit=entries.find(([k])=>normKey(k.split('.').pop())===nk)||entries.find(([k])=>normKey(k).endsWith(nk));if(hit&&clean(hit[1]))return hit[1];}return '';}
function coordsFromUrl(url){try{const u=new URL(url),s=u.href;let m=s.match(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/);if(!m){const q=u.searchParams.get('q')||u.searchParams.get('query')||'';m=q.match(/(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)/);}return m?{lat:+m[1],lng:+m[2]}:{};}catch{return {};}}
function normaliseImported(obj,source='Import'){
  if(!obj||typeof obj!=='object')return null;let base=obj;if(obj.type==='Feature')base={...(obj.properties||{}),geometry:obj.geometry};const flat=flattenObject(base);const geom=obj.geometry||base.geometry||{};const coords=Array.isArray(geom.coordinates)?geom.coordinates:[];
  const name=clean(pickFlat(flat,['name','title','restaurant name','venue','place','location name']));if(!name)return null;
  const maps=clean(pickFlat(flat,['google maps url','googlemapsurl','maps url','url','location url','link']));const urlCoords=coordsFromUrl(maps);const latRaw=pickFlat(flat,['latitude','lat']),lngRaw=pickFlat(flat,['longitude','lng','lon']);const lat=clean(latRaw)!==''&&Number.isFinite(+latRaw)?+latRaw:(coords.length>1&&clean(coords[1])!==''&&Number.isFinite(+coords[1])?+coords[1]:(urlCoords.lat??null));const lng=clean(lngRaw)!==''&&Number.isFinite(+lngRaw)?+lngRaw:(coords.length>0&&clean(coords[0])!==''&&Number.isFinite(+coords[0])?+coords[0]:(urlCoords.lng??null));
  const placeType=pickFlat(flat,obj.type==='Feature'?['place type','venue type','place category','category']:['place type','venue type','place category','category','type']);
  return canonicalPlace({id:uid(),name,placeType,cuisine:pickFlat(flat,['cuisine','cuisines','food type']),country:pickFlat(flat,['country']),stateRegion:pickFlat(flat,['state region','state','region','province']),city:pickFlat(flat,['city town','city','town','locality']),suburb:pickFlat(flat,['suburb area','suburb','area','neighbourhood','neighborhood']),address:pickFlat(flat,['formatted address','address','location']),lat,lng,price:pickFlat(flat,['price','price level']),phone:pickFlat(flat,['phone','telephone']),website:pickFlat(flat,['website','official website','web site']),googleMapsUrl:maps||googleMapsSearchUrl(name,pickFlat(flat,['address','location']),lat,lng),bookingUrl:pickFlat(flat,['booking url','reservation url','booking']),mealTypes:pickFlat(flat,['meal types','meal visit types','meal']),greatFor:pickFlat(flat,['great for']),features:pickFlat(flat,['features']),dietary:pickFlat(flat,['dietary']),tags:pickFlat(flat,['tags','personal tags']),mustTry:pickFlat(flat,['must try','what to order']),notes:pickFlat(flat,['notes','comment','comments','description']),sourceName:source,sourceId:'',sourceUrl:maps,sourceCheckedAt:nowISO(),createdAt:nowISO(),updatedAt:nowISO(),archivedAt:''});
}
function splitCsvLine(line){const out=[];let s='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){s+='"';i++;}else q=!q;}else if(c===','&&!q){out.push(s);s='';}else s+=c;}out.push(s);return out;}
async function parseImportText(name,text){const out=[],lower=name.toLowerCase();if(lower.endsWith('.csv')){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return out;const headers=splitCsvLine(lines[0]);for(const line of lines.slice(1)){const vals=splitCsvLine(line),o={};headers.forEach((h,i)=>o[h]=vals[i]??'');const p=normaliseImported(o,name.replace(/\.[^.]+$/,''));if(p)out.push(p);}return out;}try{const j=JSON.parse(text),rows=j?.type==='FeatureCollection'?j.features:Array.isArray(j)?j:(j.locations||j.places||j.features||j.saved||j.items||[j]);for(const o of rows||[]){const p=normaliseImported(o,name.replace(/\.[^.]+$/,''));if(p)out.push(p);}}catch{}return out;}
async function parseImportFiles(files){const out=[];for(const f of files){const lower=f.name.toLowerCase();if(lower.endsWith('.zip')){if(!window.JSZip)throw new Error('ZIP support did not load. Reload Pers and try again.');const zip=await JSZip.loadAsync(f);for(const [name,zf] of Object.entries(zip.files)){if(zf.dir||!/(\.csv|\.json|\.geojson)$/i.test(name))continue;const text=await zf.async('text');out.push(...await parseImportText(name,text));}}else out.push(...await parseImportText(f.name,await f.text()));}const seen=new Set();return out.filter(p=>{const k=`${normKey(p.name)}|${normKey(p.city)}|${normKey(p.address)}`;if(seen.has(k))return false;seen.add(k);return true;});}
function duplicateOf(p,excludeId=''){const url=clean(p.googleMapsUrl).replace(/\/$/,'');if(url){const hit=places.find(x=>x.id!==excludeId&&clean(x.googleMapsUrl).replace(/\/$/,'')===url);if(hit)return hit;}const name=normKey(p.name),city=normKey(p.city),address=normKey(p.address);return places.find(x=>x.id!==excludeId&&normKey(x.name)===name&&((city&&normKey(x.city)===city)||(address&&normKey(x.address)===address)));}
function renderImportPreview(){const box=$('importPreview');if(!box)return;let dup=0;importCandidates.forEach((p,i)=>{const d=duplicateOf(p);p._duplicateId=d?.id||'';if(d)dup++;if(!p._action)p._action=d?($('importDuplicatePolicy')?.value||'review'):'add';if(p._action==='review')p._action='skip';});box.innerHTML=`<p><strong>${importCandidates.length}</strong> usable place records found; <strong>${dup}</strong> possible duplicate${dup===1?'':'s'}. Choose the radio button beside the venue you want to use for the one-place test.</p>`+importCandidates.slice(0,250).map((p,i)=>{const d=p._duplicateId?places.find(x=>x.id===p._duplicateId):null;return `<div class="import-row ${i===importTestIndex?'test-pick':''}"><div><label class="import-test-pick"><input type="radio" name="importTestPick" data-import-test-pick="${i}" ${i===importTestIndex?'checked':''}> Test this venue</label><strong>${esc(p.name)}</strong><div class="muted small">Incoming: ${esc([p.city,p.country,p.cuisine].filter(Boolean).join(' · '))}</div>${d?`<div class="dup"><strong>Existing:</strong> ${esc([d.name,d.city,d.country,d.cuisine].filter(Boolean).join(' · '))}</div>`:''}</div><div class="muted small">${d?'Choose how to handle this match':'New place'}</div><select data-import-action="${i}"><option value="add" ${p._action==='add'?'selected':''}>Add as new</option>${d?`<option value="skip" ${p._action==='skip'?'selected':''}>Keep existing / skip</option><option value="merge" ${p._action==='merge'?'selected':''}>Merge missing details</option><option value="replace" ${p._action==='replace'?'selected':''}>Use imported record</option>`:''}</select></div>`;}).join('');$('runImportBtn').disabled=!importCandidates.length;const picked=importCandidates[importTestIndex];$('testImportBtn').disabled=!picked||!!(duplicateOf(picked)&&['skip','review'].includes(picked._action||''));}
async function persistImportedPlace(p,existing=null,action='add'){
  const before=existing?structuredClone(existing):null;let final=canonicalPlace({...p});const bulk=canonicalArray('tags',$('importBulkTag')?.value);if(bulk.length)final.tags=uniq([...(final.tags||[]),...bulk]);
  if(existing&&action==='merge')final=canonicalPlace(mergePlaceValues(existing,final));if(existing&&action==='replace')final={...final,id:existing.id,createdAt:existing.createdAt||final.createdAt,archivedAt:existing.archivedAt||'',updatedAt:nowISO()};
  if(existing&&(action==='merge'||action==='replace')){if(CFG.mode==='local'){Object.assign(existing,final);state.places=places;saveLocalState();}else{await rest('places',{method:'PATCH',body:appPlaceToDb(final),filters:`?id=eq.${encodeURIComponent(existing.id)}`});Object.assign(existing,final);}addPlaceValuesToLists(final);return {kind:'updated',id:existing.id,before};}
  final.id=final.id||uid();final.createdAt=final.createdAt||nowISO();final.updatedAt=nowISO();if(CFG.mode==='local'){places.push(final);state.places=places;saveLocalState();}else{const rows=await rest('places',{method:'POST',body:appPlaceToDb(final)});if(rows?.[0])final=dbPlaceToApp(rows[0]);places.push(final);}addPlaceValuesToLists(final);return {kind:'added',id:final.id,before:null};
}
async function executeImport({one=false}={}){if(!canEdit())return;const picked=importCandidates[importTestIndex];const candidates=one?(picked?[picked]:[]):importCandidates;const tx={id:uid(),at:nowISO(),changes:[]};let added=0,merged=0,replaced=0,skipped=0;await makeCheckpoint(one?'Before test import':'Before places import');for(const p of candidates){const existing=duplicateOf(p),action=p._action||($('importDuplicatePolicy')?.value||'skip');if(existing&&['skip','review'].includes(action)){skipped++;continue;}const ch=await persistImportedPlace(p,existing,existing?action:'add');tx.changes.push(ch);if(ch.kind==='added')added++;else if(action==='merge')merged++;else replaced++;if(one)break;}localStorage.setItem(LS_IMPORT_UNDO,JSON.stringify(tx));if(CFG.mode!=='local'&&tx.changes.length)try{await rest('import_transactions',{method:'POST',body:{id:tx.id,created_by:currentUser.id,transaction_json:tx}});}catch{}await saveListOptions(false);populateFilterOptions();render();const summary=`${one?'Test import':'Import'} complete: ${added} added · ${merged} merged · ${replaced} replaced · ${skipped} kept/skipped.`;$('importSummary').textContent=summary;$('importSummary').classList.remove('hidden');if(one){const imported=tx.changes[0]?.id;if(imported)openDetail(imported);toast(summary);}else{toast(summary);renderImportPreview();}}
async function undoLastImport(){if(!canEdit())return;let tx;try{tx=JSON.parse(localStorage.getItem(LS_IMPORT_UNDO)||'null');}catch{}if(!tx?.changes?.length)return toast('There is no import on this device to undo.');if(!confirm(`Undo the last import (${tx.changes.length} changed place${tx.changes.length===1?'':'s'})?`))return;await makeCheckpoint('Before undo last import');for(const ch of [...tx.changes].reverse()){if(ch.kind==='added'){const p=places.find(x=>x.id===ch.id);if(!p)continue;if(CFG.mode==='local'){places=places.filter(x=>x.id!==ch.id);state.places=places;saveLocalState();}else{await rest('places',{method:'DELETE',filters:`?id=eq.${encodeURIComponent(ch.id)}`});places=places.filter(x=>x.id!==ch.id);}}else if(ch.before){const prior=ch.before;if(CFG.mode==='local'){const i=places.findIndex(x=>x.id===ch.id);if(i>=0)places[i]=prior;state.places=places;saveLocalState();}else{await rest('places',{method:'PATCH',body:appPlaceToDb(prior),filters:`?id=eq.${encodeURIComponent(ch.id)}`});const i=places.findIndex(x=>x.id===ch.id);if(i>=0)places[i]=prior;}}}localStorage.removeItem(LS_IMPORT_UNDO);populateFilterOptions();render();if($('importSummary')){$('importSummary').textContent='Last import was undone.';$('importSummary').classList.remove('hidden');}toast('Last import undone.');}

function openBulkEdit(){if(!canEdit())return;applyFilters();$('bulkEditCount').textContent=`This will update ${filteredPlaces.length} place${filteredPlaces.length===1?'':'s'} currently shown.`;['bulkPlaceType','bulkCuisine','bulkCountry','bulkRegion','bulkCity','bulkTags'].forEach(id=>$(id).value='');$('bulkEditDialog').showModal();}
async function applyBulkEdit(){if(!canEdit())return;applyFilters();const targets=[...filteredPlaces];if(!targets.length)return toast('No places are currently shown.');if(!confirm(`Apply these changes to ${targets.length} places?`))return;const patch={placeType:canonicalValue('placeTypes',$('bulkPlaceType').value),cuisine:canonicalArray('cuisines',$('bulkCuisine').value).join(', '),country:canonicalValue('countries',$('bulkCountry').value),stateRegion:canonicalValue('regions',$('bulkRegion').value),city:canonicalValue('cities',$('bulkCity').value)},tags=canonicalArray('tags',$('bulkTags').value);await makeCheckpoint('Before bulk edit');for(const p of targets){const next={...p};for(const [k,v] of Object.entries(patch))if(v)next[k]=v;if(tags.length)next.tags=uniq([...(next.tags||[]),...tags]);next.updatedAt=nowISO();if(CFG.mode==='local')Object.assign(p,next);else{await rest('places',{method:'PATCH',body:appPlaceToDb(next),filters:`?id=eq.${encodeURIComponent(p.id)}`});Object.assign(p,next);}addPlaceValuesToLists(next);}if(CFG.mode==='local'){state.places=places;saveLocalState();}await saveListOptions(false);$('bulkEditDialog').close();populateFilterOptions();render();toast(`${targets.length} places updated.`);}

function renderSmartCollections(){const box=$('smartCollectionsList');if(!box)return;const xs=preferences.smartCollections||[];box.innerHTML=xs.length?xs.map(x=>`<span class="smart-collection"><button type="button" data-smart-load="${esc(x.id)}">${esc(x.name)}</button><button type="button" data-smart-delete="${esc(x.id)}" aria-label="Delete ${esc(x.name)}">×</button></span>`).join(''):'<span class="muted small">No saved collections yet.</span>';}
async function saveSmartCollection(){const name=clean($('smartCollectionName').value);if(!name)return toast('Enter a collection name.');preferences.smartCollections=preferences.smartCollections||[];const existing=preferences.smartCollections.find(x=>smartEq(x.name,name));const item={id:existing?.id||uid(),name,filters:structuredClone(filters)};if(existing)Object.assign(existing,item);else preferences.smartCollections.push(item);$('smartCollectionName').value='';await persistPreferences();renderSmartCollections();toast('Smart Collection saved.');}
async function handleSmartCollectionClick(e){const load=e.target.closest('[data-smart-load]'),del=e.target.closest('[data-smart-delete]');if(load){const x=(preferences.smartCollections||[]).find(y=>y.id===load.dataset.smartLoad);if(x){filters=Object.assign(defaultFilters(),x.filters);syncFilterControls();populateFilterOptions();$('accountDialog').close();render();}}if(del){preferences.smartCollections=(preferences.smartCollections||[]).filter(x=>x.id!==del.dataset.smartDelete);await persistPreferences();renderSmartCollections();}}

function quickFilter(which){if(which==='near'){if(!currentPosition)requestLocation();filters.distance=preferences.preferredDistance||'5';}if(which==='tonight'){if(!currentPosition)requestLocation();filters.type='Restaurant';filters.meal='Dinner';filters.distance=preferences.preferredDistance||'5';}if(which==='five')filters.rating=filters.rating==='5'?'':'5';if(which==='favourite')filters.status=filters.status==='favourite'?'':'favourite';if(which==='want')filters.status=filters.status==='want'?'':'want';if(which==='restaurant')filters.type=filters.type==='Restaurant'?'':'Restaurant';if(which==='winebar')filters.type=filters.type==='Wine Bar'?'':'Wine Bar';syncFilterControls();render();if(which==='tonight')toast('Tonight shows nearby dinner restaurants; opening hours are not assumed.');}

function renderList(){const box=$('listPanel');if(!filteredPlaces.length){box.innerHTML='<div class="empty">No places match these filters.</div>';return;}box.innerHTML=filteredPlaces.map(p=>{const x=getPersonal(p.id),d=distanceFor(p),meta=[p.placeType,p.cuisine,p.city,p.price,d!=null?`${d<1?Math.round(d*1000)+' m':d.toFixed(1)+' km'}`:''].filter(Boolean).join(' · '),status=x.want?'Want to Try':x.visited?'Visited':x.favourite?'Favourite':'',cover=coverPhotoForPlace(p.id),initials=esc(p.name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'PF'),visual=cover?`<img class="place-card-cover" data-photo-id="${cover.id}" alt="Photo of ${esc(p.name)}" />`:`<div class="place-card-placeholder">${initials}</div>`;return `<article class="place-card ${cover?'has-photo':''}" data-place="${p.id}">${visual}<div class="place-card-inner"><div class="place-card-top"><div><h3>${esc(p.name)}</h3><div class="meta">${esc(meta)}</div>${status?`<span class="status-pill">${esc(status)}</span>`:''}</div><div class="rating">${esc(formatRating(x.rating))}</div></div>${p.mustTry?`<div class="must-try"><strong>Must try:</strong> ${esc(p.mustTry)}</div>`:''}<div class="card-actions"><button data-open="${p.id}">Open venue</button>${safeUrl(p.googleMapsUrl)?`<a href="${esc(safeUrl(p.googleMapsUrl))}" target="_blank" rel="noopener">Directions</a>`:''}${safeUrl(p.website)?`<a href="${esc(safeUrl(p.website))}" target="_blank" rel="noopener">Website</a>`:''}${p.phone?`<a href="tel:${esc(p.phone.replace(/[^+\d]/g,''))}">Call</a>`:''}${safeUrl(p.bookingUrl)?`<a href="${esc(safeUrl(p.bookingUrl))}" target="_blank" rel="noopener">Book</a>`:''}<button data-card-share="${p.id}">Share</button>${canEdit()?`<button data-edit="${p.id}">Edit</button>`:''}</div></div></article>`;}).join('');hydratePhotoImages(box);}
function openDetail(id){const p=places.find(x=>x.id===id);if(!p)return;activeDetailPlaceId=id;const x=getPersonal(id),d=distanceFor(p),cover=coverPhotoForPlace(id),ownerName=state?.settings?.ownerDisplayName||CFG.ownerDisplayName||'Owner',count=visitCount(id),hero=cover?`<div class="detail-hero"><img data-photo-id="${cover.id}" alt="Photo of ${esc(p.name)}" /></div>`:`<div class="detail-hero"><div class="detail-hero-empty">${esc(p.name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'PF')}</div></div>`;$('detailName').textContent=p.name;$('detailBody').innerHTML=`${hero}<div class="detail-grid"><div class="k">Type</div><div>${esc([p.placeType,p.cuisine].filter(Boolean).join(' · ')||'—')}</div><div class="k">Location</div><div>${esc([p.suburb,p.city,p.stateRegion,p.country].filter(Boolean).join(', ')||'—')}</div><div class="k">Distance</div><div>${d==null?'—':esc(d<1?Math.round(d*1000)+' m':d.toFixed(1)+' km')}</div><div class="k">Price</div><div>${esc(p.price||'—')}</div><div class="k">Must try</div><div>${esc(p.mustTry||'—')}</div><div class="k">${esc(ownerName)} says</div><div>${esc(p.notes||'—')}</div><div class="k">Tags</div><div>${esc((p.tags||[]).join(', ')||'—')}</div><div class="k">Visits</div><div>${count}${x.lastVisited?` · last ${esc(new Date(x.lastVisited).toLocaleDateString())}`:''}</div></div>${p.sourceName?`<div class="detail-grid source-grid"><div class="k">Online source</div><div>${safeUrl(p.sourceUrl)?`<a href="${esc(safeUrl(p.sourceUrl))}" target="_blank" rel="noopener">${esc(p.sourceName)}</a>`:esc(p.sourceName)}</div></div>`:''}${renderPhotoGallery(id)}<div class="personal-panel"><strong>My view</strong><div class="stars" data-stars="${id}">${[1,2,3,4,5].map(n=>`<button data-rate="${n}" class="${n<=x.rating?'on':''}" aria-label="${n} stars">★</button>`).join('')}</div><label class="check"><input type="checkbox" data-personal="favourite" ${x.favourite?'checked':''}> Favourite</label><label class="check"><input type="checkbox" data-personal="want" ${x.want?'checked':''}> Want to Try</label><label class="check"><input type="checkbox" data-personal="visited" ${x.visited?'checked':''}> Visited</label><label>Would go again<select id="detailWouldGoAgain"><option value="" ${!x.wouldGoAgain?'selected':''}>Not set</option><option value="yes" ${x.wouldGoAgain==='yes'?'selected':''}>Yes</option><option value="no" ${x.wouldGoAgain==='no'?'selected':''}>No</option></select></label><label>Private note<textarea id="detailPrivateNote" rows="2">${esc(x.privateNote||'')}</textarea></label><button class="secondary" data-save-personal="${id}">Save my details</button> <button class="secondary" data-log-visit="${id}">Log visit</button></div><div class="card-actions">${safeUrl(p.googleMapsUrl)?`<a href="${esc(safeUrl(p.googleMapsUrl))}" target="_blank" rel="noopener">Directions</a><a href="${esc(safeUrl(p.googleMapsUrl))}" target="_blank" rel="noopener">Google reviews & photos</a>`:''}${safeUrl(p.website)?`<a href="${esc(safeUrl(p.website))}" target="_blank" rel="noopener">Website</a>`:''}${p.phone?`<a href="tel:${esc(p.phone.replace(/[^+\d]/g,''))}">Call</a>`:''}${safeUrl(p.bookingUrl)?`<a href="${esc(safeUrl(p.bookingUrl))}" target="_blank" rel="noopener">Book</a>`:''}${safeUrl(p.sourceUrl)?`<a href="${esc(safeUrl(p.sourceUrl))}" target="_blank" rel="noopener">Source</a>`:''}<button data-share="${p.id}">Share</button>${canEdit()?`<button data-edit="${p.id}">Edit venue</button>`:''}</div>`;if(!$('detailDialog').open)$('detailDialog').showModal();hydratePhotoImages($('detailBody'));}
async function savePersonalFromDetail(id){const old=getPersonal(id),next={...old,privateNote:$('detailPrivateNote')?.value||'',wouldGoAgain:$('detailWouldGoAgain')?.value||''};$('detailBody').querySelectorAll('[data-personal]').forEach(el=>next[el.dataset.personal]=el.checked);personal[personalKey(id)]=next;if(CFG.mode==='local'){state.personal=personal;saveLocalState();}else if(usesDevicePersonalState()){savePublicViewerState();}else await rest('personal_place_data',{method:'POST',body:{user_id:currentUser.id,place_id:id,rating:next.rating,favourite:next.favourite,want_to_visit:next.want,visited:next.visited,private_note:next.privateNote,last_visited:next.lastVisited||null,would_go_again:next.wouldGoAgain||''}});toast('Personal details saved');render();}

function applyAskPlan(plan){const f=plan?.filters||{};filters=defaultFilters();$('searchInput').value='';const map={country:'country',region:'region',city:'city',placeType:'type',cuisine:'cuisine',status:'status',meal:'meal',greatFor:'greatFor',feature:'feature',dietary:'dietary',tag:'tag'};for(const [pk,fk] of Object.entries(map))if(clean(f[pk]))filters[fk]=f[pk];if(+f.minRating)filters.rating=String(f.minRating);if(+f.maxDistanceKm){filters.distance=String(f.maxDistanceKm);if(!currentPosition)requestLocation();}const text=[clean(f.text),clean(f.suburb)].filter(Boolean).join(' ');if(text)$('searchInput').value=text;if(plan.sort)$('sortSelect').value=plan.sort;syncFilterControls();populateFilterOptions();render();if(clean(f.wouldGoAgain)){filteredPlaces=filteredPlaces.filter(p=>clean(getPersonal(p.id).wouldGoAgain)===clean(f.wouldGoAgain));renderList();if(preferences.view==='map')renderMap();$('resultCount').textContent=`${filteredPlaces.length} ${filteredPlaces.length===1?'place':'places'}`;}return filteredPlaces;}
function aggregateAsk(plan,xs){const metric=plan.metric||'count',group=plan.groupBy||'';if(!group){if(metric==='averageRating'){const vals=xs.map(p=>+getPersonal(p.id).rating).filter(Boolean);return vals.length?`Average personal rating: ${(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(1)} across ${vals.length} rated places.`:'No rated places matched.';}if(metric==='visits')return `${xs.reduce((n,p)=>n+visitCount(p.id),0)} logged visits across ${xs.length} matching places.`;return `${xs.length} places matched.`;}const groups=new Map();for(const p of xs){let keys=[];if(group==='tag')keys=p.tags||[];else if(group==='cuisine')keys=arr(p.cuisine);else keys=[p[group]||'Unspecified'];for(const k of keys.filter(Boolean)){if(!groups.has(k))groups.set(k,[]);groups.get(k).push(p);}}const rows=[...groups].map(([k,v])=>({k,v,score:metric==='visits'?v.reduce((n,p)=>n+visitCount(p.id),0):metric==='averageRating'?(()=>{const a=v.map(p=>+getPersonal(p.id).rating).filter(Boolean);return a.length?a.reduce((x,y)=>x+y,0)/a.length:0})():v.length})).sort((a,b)=>b.score-a.score).slice(0,plan.topN||5);return rows.length?rows.map(r=>`${r.k}: ${metric==='averageRating'?r.score.toFixed(1):r.score}`).join(' · '):'No matching groups.';}
async function askPers(e){e?.preventDefault?.();const q=clean($('askPersInput').value);if(q.length<3)return;$('askPersBtn').disabled=true;$('askPersStatus').textContent='Interpreting your question…';try{let plan;if(CFG.mode==='local'){plan=localAskPlan(q);}else{const out=await cfFetch('/api/public?action=ask-pers',{method:'POST',body:{question:q}});plan=out.plan;$('askPersStatus').dataset.remaining=out.remaining??'';}const xs=applyAskPlan(plan);const answer=plan.mode==='aggregate'?aggregateAsk(plan,xs):`${xs.length} matching place${xs.length===1?'':'s'} shown below.`;$('askPersStatus').innerHTML=`<div class="ask-answer">${esc(answer)}</div>`;}catch(err){$('askPersStatus').textContent=err.message||'Ask Pers could not interpret that question.';}finally{$('askPersBtn').disabled=false;}}
function localAskPlan(q){const n=normKey(q),f={text:'',country:'',region:'',city:'',suburb:'',placeType:'',cuisine:'',minRating:0,maxDistanceKm:0,status:'',meal:'',greatFor:'',feature:'',dietary:'',tag:'',wouldGoAgain:''};for(const c of COUNTRY_NAMES)if(n.includes(normKey(c)))f.country=c;for(const c of mergedListValues('cities'))if(n.includes(normKey(c)))f.city=c;for(const c of mergedListValues('cuisines'))if(n.includes(normKey(c)))f.cuisine=c;for(const [alias,target] of Object.entries(VALUE_ALIASES.cuisines||{}))if(n.includes(alias))f.cuisine=target;for(const t of mergedListValues('placeTypes'))if(n.includes(normKey(t)))f.placeType=t;if(/want to try/.test(q.toLowerCase()))f.status='want';else if(/haven.?t (visited|tried)|not visited|not tried|never (visited|tried)/.test(q.toLowerCase()))f.status='unvisited';else if(/visited|been to/.test(q.toLowerCase()))f.status='visited';if(/favourite|favorite/.test(q.toLowerCase()))f.status='favourite';const m=q.match(/([1-5])\s*(?:star|\+)/i);if(m)f.minRating=+m[1];if(/nearby|near me|tonight/.test(q.toLowerCase()))f.maxDistanceKm=+(preferences.preferredDistance||5);if(/tonight|dinner/.test(q.toLowerCase())){f.meal='Dinner';if(!f.placeType)f.placeType='Restaurant';}const aggregate=/which|most|how many|average|prefer|top cuisine/i.test(q);return {mode:aggregate?'aggregate':'search',filters:f,sort:f.maxDistanceKm?'nearest':'rating',groupBy:/cuisine/i.test(q)&&aggregate?'cuisine':'',metric:/average/i.test(q)?'averageRating':/visit/i.test(q)&&aggregate?'visits':'count',topN:5};}

function openAccount(){const anon=isAnonymousViewer();$('accountSummary').innerHTML=anon?`<strong>Browsing as Viewer</strong><br><span class="muted">No login required</span>`:`<strong>${esc(currentUser?.displayName||currentUser?.email||'Local test')}</strong><br><span class="muted">${esc((currentUser?.role||'viewer').toUpperCase())}</span>${currentUser?.email?` · ${esc(currentUser.email)}`:''}`;$('ownerSigninBtn').classList.toggle('hidden',CFG.mode==='local'||!!session);$('contributorSigninBtn').classList.toggle('hidden',CFG.mode==='local'||!!session);$('editorSettings').classList.toggle('hidden',!canEdit());if(canEdit())renderListSetup();$('ownerSettings').classList.toggle('hidden',!isOwner());$('localRoleSettings').classList.toggle('hidden',CFG.mode!=='local');if(CFG.mode==='local')$('localRoleSelect').value=currentUser.role;$('settingAppName').value=state.settings.appName||'';$('settingOwnerName').value=state.settings.ownerDisplayName||'';$('settingHomeRegion').value=state.settings.homeRegion||'';$('settingAllowUserPhotos').checked=state.settings.allowUserPhotos!==false;$('settingAskPersEnabled').checked=!!state.settings.askPersEnabled;$('settingAskPersDailyLimit').value=state.settings.askPersDailyLimit||50;$('rememberFilters').checked=!!preferences.rememberFilters;$('prefDistance').value=preferences.preferredDistance||'5';renderSmartCollections();updatePendingPhotoBadge();$('signOutBtn').classList.toggle('hidden',CFG.mode!=='local'&&!session);$('accountDialog').showModal();}
async function saveCollectionSettings(){if(!isOwner())return toast('Only the Owner can change collection settings.');const s={appName:clean($('settingAppName').value)||CFG.appName,ownerDisplayName:clean($('settingOwnerName').value),homeRegion:clean($('settingHomeRegion').value),allowUserPhotos:!!$('settingAllowUserPhotos').checked,askPersEnabled:!!$('settingAskPersEnabled').checked,askPersDailyLimit:Math.max(1,Math.min(500,+$('settingAskPersDailyLimit').value||50))};await makeCheckpoint('Before collection settings change');if(CFG.mode==='local'){state.settings={...state.settings,...s};saveLocalState();}else{await cfFetch('/api/admin?action=save-settings',{method:'POST',body:s});state.settings={...state.settings,...s};}setBranding();updateAskPersVisibility();toast('Collection settings saved');}
function updateAskPersVisibility(){$('askPersSection')?.classList.toggle('hidden',!state?.settings?.askPersEnabled);}
function showApp(){if($('authScreen')?.open)$('authScreen').close();$('localStartScreen').classList.add('hidden');$('appScreen').classList.remove('hidden');setBranding();applyPreferencesToUI();populateFilterOptions();updateAskPersVisibility();render();if(CFG.mode!=='local'&&session){const pending=sessionStorage.getItem('pers-v027-pending-photo-place');if(pending&&places.some(p=>p.id===pending)){sessionStorage.removeItem('pers-v027-pending-photo-place');setTimeout(()=>openDetail(pending),150);}}}
function openAuth(purpose='owner'){authPurpose=purpose;$('authTitle').textContent=purpose==='contributor'?'Contribute venue photos':'Owner / Admin sign in';$('authIntro').textContent=purpose==='contributor'?'Browsing never requires a login. Cloudflare Access will verify your identity only for the contribution action.':'Owner/Admin controls are protected by Cloudflare Access.';$('loginBtn').classList.toggle('hidden',purpose==='contributor');$('magicLinkBtn').classList.toggle('hidden',purpose!=='contributor');$('authMessage').textContent='';$('authScreen').showModal();}
async function signOut(){await persistPreferences();localStorage.removeItem(LS_SESSION);if(CFG.mode==='local')return location.reload();session=null;location.href='/cdn-cgi/access/logout';}
async function exportHistory(){if(CFG.mode==='local'){exportJson({appVersion:CFG.version,deploymentId:CFG.deploymentId,exportedAt:nowISO(),history:state.history},`pers-favourites-v027c-history-${new Date().toISOString().slice(0,10)}.json`);return;}try{const rows=await rest('audit_snapshots',{filters:'&order=created_at.desc&limit=50'});exportJson({appVersion:CFG.version,deploymentId:CFG.deploymentId,exportedAt:nowISO(),history:rows},`pers-favourites-v027c-history-${new Date().toISOString().slice(0,10)}.json`);}catch(e){toast(e.message);}}

