  $('startLocalBtn').onclick=()=>{localStorage.setItem(LS_SESSION,'local-started');enterLocal();};$('authClose').onclick=()=>$('authScreen').close();$('loginBtn').onclick=()=>{localStorage.setItem(LS_SESSION,JSON.stringify({provider:'cloudflare',purpose:'admin'}));location.href='/api/admin?action=login';};$('magicLinkBtn').onclick=()=>{sessionStorage.setItem('pers-v027-pending-photo-place',pendingContributionPlaceId||activeDetailPlaceId||'');localStorage.setItem(LS_SESSION,JSON.stringify({provider:'cloudflare',purpose:'contribute'}));location.href='/api/contribute?action=login';};
