  $('listPanel').onclick=e=>{const open=e.target.closest('[data-open]'),edit=e.target.closest('[data-edit]'),share=e.target.closest('[data-card-share]');if(open)openDetail(open.dataset.open);if(edit)openPlaceEditor(edit.dataset.edit);if(share)sharePlace(share.dataset.cardShare);};$('detailClose').onclick=()=>{$('detailDialog').close();activeDetailPlaceId='';};$('detailBody').onclick=e=>{const r=e.target.closest('[data-rate]'),s=e.target.closest('[data-save-personal]'),v=e.target.closest('[data-log-visit]'),sh=e.target.closest('[data-share]'),ed=e.target.closest('[data-edit]'),add=e.target.closest('[data-add-photo]'),po=e.target.closest('[data-photo-open]'),pa=e.target.closest('[data-photo-approve]'),ph=e.target.closest('[data-photo-hide]'),pc=e.target.closest('[data-photo-cover]'),pca=e.target.closest('[data-photo-caption]'),pe=e.target.closest('[data-photo-earlier]'),pl=e.target.closest('[data-photo-later]'),pd=e.target.closest('[data-photo-delete]');if(r)setRating(r.closest('[data-stars]').dataset.stars,+r.dataset.rate);if(s)savePersonalFromDetail(s.dataset.savePersonal);if(v)logVisit(v.dataset.logVisit);if(sh)sharePlace(sh.dataset.share);if(add){activeDetailPlaceId=add.dataset.addPhoto;if(!canEdit()&&state?.settings?.allowUserPhotos===false)toast('The Owner has turned off user photo contributions.');else if(isAnonymousViewer()){pendingContributionPlaceId=activeDetailPlaceId;openAuth('contributor');}else $('photoInput').click();}if(po)openPhotoViewer(po.dataset.photoOpen);if(pa)setPhotoState(pa.dataset.photoApprove,'approved');if(ph)setPhotoState(ph.dataset.photoHide,'hidden');if(pc)setCoverPhoto(pc.dataset.photoCover);if(pca)editPhotoCaption(pca.dataset.photoCaption);if(pe)movePhoto(pe.dataset.photoEarlier,-1);if(pl)movePhoto(pl.dataset.photoLater,1);if(pd)deletePhoto(pd.dataset.photoDelete);if(ed){$('detailDialog').close();openPlaceEditor(ed.dataset.edit);}};
  $('importBtn').onclick=()=>$('importDialog').showModal();$('importClose').onclick=()=>$('importDialog').close();$('importFiles').onchange=async()=>{try{$('importSummary').classList.add('hidden');$('importSummary').textContent='';$('importPreview').innerHTML='<p>Reading files…</p>';importCandidates=await parseImportFiles([...$('importFiles').files]);importTestIndex=0;renderImportPreview();}catch(e){$('importPreview').textContent=e.message;}};$('importDuplicatePolicy').onchange=()=>{for(const p of importCandidates)if(p._duplicateId)p._action=$('importDuplicatePolicy').value==='review'?'skip':$('importDuplicatePolicy').value;renderImportPreview();};$('importPreview').onchange=e=>{const a=e.target.closest('[data-import-action]'),t=e.target.closest('[data-import-test-pick]');if(a){importCandidates[+a.dataset.importAction]._action=a.value;renderImportPreview();}if(t){importTestIndex=+t.dataset.importTestPick;renderImportPreview();}};$('runImportBtn').onclick=()=>executeImport({one:false});$('testImportBtn').onclick=()=>executeImport({one:true});$('undoImportBtn').onclick=undoLastImport;
